% op_mergesubspec.m
% Helge Zoellner, Johns Hopkins University 2021.
% 
% USAGE:
% out=op_mergesubspec(varargin);
% 
% DESCRIPTION:
% Merges input structs into the subspectra dimension
% 
% INPUTS:
% varargin     = input data in matlab structure format.
%
% OUTPUTS:
% out    = Output dataset with merged subspectra

function out=op_mergesubspec(varargin);
in1 = varargin{1};

if isempty(varargin{2}) %Check if the first argument to be a null string
    error('You have to at least put in two structs')
else

    for ss = 2 : length(varargin)
        in2 = varargin{ss};
        if in1.dims.subSpecs~=0 && in2.dims.subSpecs~=0 && in1.dims.subSpecs ~= in2.dims.subSpecs
            %RULE:  Averages dimension must be the same for both inputs UNLESS one of
            %the inputs has an averages dimension of zero:
            error('subspectra dimensions must be the same for both inputs');
        end

        if in1.dims.subSpecs==0 && in2.dims.subSpecs==0
            dim=2;
        elseif in1.dims.subSpecs==0
            dim=in2.dims.subSpecs;
        elseif in2.dims.averages==0;
            dim=in1.dims.subSpecs;
        else
            dim=in1.dims.subSpecs;
        end
        if ~contains(in1.names,in2.names(1))
            in1.fids=cat(dim,in1.fids,in2.fids);
            in1.specs=cat(dim,in1.specs,in2.specs);
            in1.subspecs=in1.subspecs+in2.subspecs;
            in1.names{end+1} = in2.names{1};
        else
            ind = find(strcmp(in1.names,in2.names(1)));
            in1.fids(:,ind,:,:,:,:,:) = in2.fids(:,1,:,:,:,:,:);
            in1.specs(:,ind,:,:,:,:,:) = in2.specs(:,1,:,:,:,:,:);
        end

    end
    sz=size(in1.fids);

    %FILLING IN DATA STRUCTURE
    out=in1;
    out.sz=sz;
%     out.rawAverages=in1.rawAverages+in2.rawAverages;
    if in1.dims.subSpecs==0
        out.dims.subSpecs=dim;
    end


    %FILLING IN THE FLAGS
    out.flags=in1.flags;
    out.flags.writtentostruct=1;
end

function [out,switchOrder] = osp_onOffClassifyMEGA(in, target,Order)
%% [outA,switchOrder] = osp_onOffClassifyMEGA(in,target)
%   This function decides which of the two provided MEGA sub-spectra in the
%   are the edit-ON or the edit-OFF.
%
%   To this end, the difference spectrum is analyzed. For GABA-edited data,
%   the NAA peak is investigated; for GSH-edited data, the residual water
%   peak.
%
%   The function then assigns the edit-OFF spectrum to field A, and the
%   edit-ON spectrum to field B.
%
%   USAGE:
%       [out] = osp_onOffClassifyMEGA(in, target, Order)
%
%   INPUTS:
%       in     = FID-A structure containing MEGA spectrum.
%       target  = String. Can be 'GABA' or 'GSH'.
%       Order = manually overwrite order
%
%   OUTPUTS:
%       out    = FID-A structure containing the ordered MEGA sub-spectrum.
%       switchOrder = Vector indicating the order in which the input
%               spectra are rearranged in order to generate the output order.
%
%   AUTHOR:
%       Dr. Georg Oeltzschner (Johns Hopkins University, 2019-03-18)
%       goeltzs1@jhmi.edu
%           
%   
%   CREDITS:    
%       This code is based on numerous functions from the FID-A toolbox by
%       Dr. Jamie Near (McGill University)
%       https://github.com/CIC-methods/FID-A
%       Simpson et al., Magn Reson Med 77:23-33 (2017)
%
%   HISTORY:
%       2019-03-18: First version of the code.
%       2020-01-15: Modified by Helge Zoellner (absolute value
%       implementation)

if nargin < 2
    target = 'GABA';
    Order = [];
end
if nargin < 3
    Order = [];
end
out = in;
if isempty(Order)
    switch target
        case 'GABA'
            % Determine which of the differences has an upright NAA peak
            temp = op_freqrange(in, 1.7, 2.3);        
        case 'GSH'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 4, 5);
        case 'Lac'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.8, 4);
        case 'PE398'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.8, 4.1);       
        case 'PE322'
            % Determine which of the differences has an upright water peak
            temp = op_freqrange(in, 3.0, 3.3);     
        otherwise
            disp('MEGA ON/OFF classifier does not recognize the input argument ''target''. We automatically assume no reordering. You can change that in osp_onOFFClassifyMEGA.m');
             outA = inA;
            outB = inB;
            switchOrder = 0;
    end

    spec = abs(real(temp.specs));        
    max_diffAB = max(spec(:,1) - spec(:,2));
    max_diffBA = max(spec(:,2) - spec(:,1));


    if max_diffAB > max_diffBA

        switchOrder = 0;
    else
        temp = in;
        out.specs(:,1) = temp.specs(:,2);
        out.specs(:,2) = temp.specs(:,1);
        out.fids(:,1) = temp.fids(:,2);
        out.fids(:,2) = temp.fids(:,1);
        switchOrder = 1;
    end
else
    switchOrder = Order;
    if switchOrder
        temp = in;
        out.specs(:,1) = temp.specs(:,2);
        out.specs(:,2) = temp.specs(:,1);
        out.fids(:,1) = temp.fids(:,2);
        out.fids(:,2) = temp.fids(:,1);
    end
end

end

