function [out] = op_combine_water_subspecs(in,average)
% Some formats end up having subspectra in their reference scans
% (e.g. Philips), as well as empty lines. Intercept these cases
% here.
if nargin < 2
    average = 1;
end
    out = in;
    if out.subspecs == 2
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        out                 = op_concatAverages(raw_A,raw_B);
    end

    if out.subspecs == 4
        raw_A               = op_takesubspec(out,1);
        [raw_A]             = op_rmempty(raw_A);            % Remove empty lines
        raw_B               = op_takesubspec(out,2);
        [raw_B]             = op_rmempty(raw_B);            % Remove empty lines
        raw_C               = op_takesubspec(out,3);
        [raw_C]             = op_rmempty(raw_C);            % Remove empty lines
        raw_D               = op_takesubspec(out,4);
        [raw_D]             = op_rmempty(raw_D);            % Remove empty lines
        out                 = op_concatAverages(op_concatAverages(raw_A,raw_B),op_concatAverages(raw_C,raw_D));
    end
    if out.subspecs == 1
        [out]             = op_rmempty(out);            % Remove empty lines
    end
    if average
        % Align and verage the refernce data
        if out.averages > 1 && ~out.flags.averaged
            [out]             = op_rmempty(out);
            [out,~,~]               = op_alignAverages(out, 1, 'n');
            out                     = op_averaging(out);            % Average
        else
            out.flags.averaged  = 1;
            out.dims.averages   = 0;
        end
    end
    out.names = {'A'};
end

% op_rmempty.m
% Georg Oeltzschner, Johns Hopkins University 2018.
% 
% USAGE:
% [out]=op_rmempty(in);
% 
% DESCRIPTION:
% Removes empty FIDs (for example in Philips *_ref.sdat files).
% 
% INPUTS:
% in        = input data in matlab structure format.
%
% OUTPUTS:
% out       = Output dataset


function [out]=op_rmempty(in)

if ~in.flags.averaged

    % If the standard deviation of an FID is ~0, this FID row is empty.
    % Find the indices of the averages with non-zero standard deviations -
    % these are the ones that will be 
    idx_nonzeroFID = find(std(in.fids,0,1)>1e-40);
    nonzero_fids = in.fids(:,idx_nonzeroFID);

    %reshape if still not coil combined
    if length(in.sz) > 2
        nonzero_fids = reshape(nonzero_fids,in.sz);
    end
    %re-calculate Specs using fft
    nonzero_specs=fftshift(fft(nonzero_fids,[],in.dims.t),in.dims.t);

    %recalculate the sz vector
    sz=size(nonzero_fids);

    % 
    %FILLING IN DATA STRUCTURES
    out=in;
    out.fids=nonzero_fids;
    out.specs=nonzero_specs;
    out.sz=sz;
    out.averages=sz(2);

    %FILLING IN THE FLAGS
    out.flags=in.flags;
else
    out = in;
end

