function [ppm, spectra] = build_spectra(c)
ppm = linspace(c.ppm_min, c.ppm_max, c.npts)';
ref_shape = exp(-0.5*((ppm - c.ref_c)./c.ref_w).^2);
ed_shape = exp(-0.5*((ppm - c.ed_c)./c.ed_w).^2);
nsub = numel(c.ref_amp);
spectra = zeros(c.npts, nsub);
for ii = 1:nsub
    ph = c.phase(ii)*pi/180;
    sig = c.ref_amp(ii).*ref_shape + c.ed_amp(ii).*ed_shape;
    spectra(:, ii) = real(sig .* complex(cos(ph), sin(ph)));
end
end

function obs = observe(ppm, spectra, c)
mask = abs(ppm - c.ref_c) <= max(c.ref_w*3.5, 0.08);
w = real(spectra(mask, :));
pol = zeros(1, columns(w));
nrm = zeros(1, columns(w));
for ii = 1:columns(w)
    [~, idx] = max(abs(w(:, ii)));
    pol(ii) = sign(w(idx, ii) + (w(idx,ii) == 0));
    nrm(ii) = norm(w(:, ii));
end
obs.consist = mean(pol == pol(1));
obs.retained = norm(mean(w, 2))/max(mean(nrm), 1e-12);
obs.pol = pol;
end

function ok = report_loaded(tag, loaded, ppm, spectra, c)
specs = loaded.specs;
if isfield(loaded.dims, 'averages') && loaded.dims.averages > 0
    specs = mean(specs, loaded.dims.averages);
end
specs = squeeze(specs);
if isvector(specs); specs = specs(:); end
obs = observe(ppm, specs, c);
ok = all(isfinite(loaded.fids(:)));
fprintf('  %s: signconsist=%.3f retained=%.4f pol=[%s] finite=%d shape=[%s]\n', tag, ...
    obs.consist, obs.retained, num2str(obs.pol), ok, num2str(size(loaded.specs)));
end

function path_sdat = write_sdat(work_dir, name, spectra, navg, add_empty)
if nargin < 5; add_empty = false; end
path_sdat = fullfile(work_dir, [name '.sdat']);
spar = fullfile(work_dir, [name '.spar']);
samples = rows(spectra);
nsub = columns(spectra);
nrows = nsub*navg;
src = ifft(ifftshift(spectra, 1), [], 1);
fid_data = zeros(samples, nrows);
for aa = 1:navg
    for ss = 1:nsub
        fid_data(:, (aa-1)*nsub + ss) = src(:, ss);
    end
end
if add_empty
