function fids = undoReceiverPhaseCycle(fids)
% Undo the phase cycling of the receiver by removing the zero-order phase
% of the first point of every FID (i.e. of every average of every
% sub-spectrum). This is the operation that is also applied to Philips data
% that is read through the NIfTI-MRS loader (io_loadspec_niimrs).
% All-zero FIDs (e.g. the empty rows of Philips reference scans) are left
% untouched instead of being turned into NaNs.

firstPoints  = fids(1,:,:,:,:,:);
magnitudes   = abs(firstPoints);
phaseFactors = conj(firstPoints);
nonZero      = magnitudes > 0;
phaseFactors(nonZero)  = phaseFactors(nonZero)./magnitudes(nonZero);
phaseFactors(~nonZero) = 1;
fids = fids .* repmat(phaseFactors,[size(fids,1) 1]);

end


function undoPhaseCycle = parseUndoPhaseCycle(undoPhaseCycle)
% Interpret the optional phase cycle/polarity switch. Anything empty or
% missing falls back to the default, i.e. undoing the phase cycle so that
% the sub-spectra of edited data are polarity-consistent. Workflows that
% intentionally preserve the original acquisition polarity switch this off
% (undoPhaseCycle = 0, or a settings struct with undoPhaseCycle = 0 /
% PreservePolarity = 1).

if isempty(undoPhaseCycle)
    undoPhaseCycle = true;
    return
end

if isstruct(undoPhaseCycle)
    opts = undoPhaseCycle;
    if isfield(opts,'load') && isstruct(opts.load) && isfield(opts.load,'undoPhaseCycle')
        undoPhaseCycle = parseUndoPhaseCycle(opts.load.undoPhaseCycle);
    elseif isfield(opts,'undoPhaseCycle')
        undoPhaseCycle = parseUndoPhaseCycle(opts.undoPhaseCycle);
    elseif isfield(opts,'PreservePolarity')
        undoPhaseCycle = ~parseUndoPhaseCycle(opts.PreservePolarity);
    else
        undoPhaseCycle = true;
    end
    return
end

if ischar(undoPhaseCycle)
    switch lower(strtrim(undoPhaseCycle))
        case {'undophasecycle','undo','n','no'}
            undoPhaseCycle = true;
        case {'preservepolarity','preserve','keeppolarity','y','yes'}
            undoPhaseCycle = false;
        otherwise
            error('io_loadspec_sdat: unrecognized phase cycle option ''%s''.',undoPhaseCycle);
    end
    return
end

if ~(isnumeric(undoPhaseCycle) || islogical(undoPhaseCycle)) || numel(undoPhaseCycle) ~= 1
    error('io_loadspec_sdat: the undoPhaseCycle input has to be a scalar flag.');
end
undoPhaseCycle = logical(undoPhaseCycle);

end

