% INPUTS:
% in    = input data in matlab structure format
% A     = Amplitude scaling factor.  Either a single factor that is applied
%         to the entire dataset, or one factor per sub-spectrum (e.g. the
%         polarity factors of edited MRS data).
%
% OUTPUTS:
% out   = Output following amplitude scaling.

function out=op_ampScale(in,A);

sz_A = numel(A);
out=in;
if sz_A == 1
    out.specs=in.specs*A;
    out.fids=in.fids*A;
else
    % One factor per sub-spectrum. Apply the factors along the sub-spectra
    % dimension, so that each factor stays attached to its own
    % sub-spectrum, no matter which other dimensions (coils, averages,
    % extras) are still present in the dataset.
    dim = 0;
    if isfield(in,'dims') && isfield(in.dims,'subSpecs') && in.dims.subSpecs > 0 && ...
            size(in.fids,in.dims.subSpecs) == sz_A
        dim = in.dims.subSpecs;
    elseif size(in.fids,ndims(in.fids)) == sz_A
        % Fall back to the last dimension (legacy behaviour)
        dim = ndims(in.fids);
    end
    if dim == 0
        error('ERROR:  The number of scaling factors does not match the number of sub-spectra!  ABORTING!!');
    end

    idx = repmat({':'},1,ndims(in.fids));
    for ss = 1 : sz_A
        idx_ss = idx;
        idx_ss{dim} = ss;
        out.specs(idx_ss{:}) = in.specs(idx_ss{:})*A(ss);
        out.fids(idx_ss{:})  = in.fids(idx_ss{:})*A(ss);
    end
end

