function lines = extract_block(path)
txt = fileread(path);
lines = strsplit(txt, sprintf('\n'));
first = find(~cellfun(@isempty, strfind(lines, '5. DETERMINE POLARITY OF SPECTRUM')), 1);
last  = find(~cellfun(@isempty, strfind(lines, '6. DETERMINE ON/OFF STATUS')), 1);
lines = lines(first:last-1);
end

function MRSCont = base_cont(raw_unavg)
MRSCont = struct();
MRSCont.opts = struct();
MRSCont.flags.hasMM = 0;
MRSCont.raw = {raw_unavg};
end

function [avg, unavg] = make_struct(polarities, nsub, with_coils)
if nargin < 3; with_coils = false; end
npts = 512; navg = 3; ncoils = 2;
sw = 2000; txfrq = 127731000;
Bo = txfrq/42577000;
f = (-sw/2)+(sw/(2*npts)):sw/npts:(sw/2)-(sw/(2*npts));
ppm = f/(Bo*42.577) + 4.68;
cr = exp(-0.5*((ppm(:) - 3.02)./0.03).^2);
nag = 0.4*exp(-0.5*((ppm(:) - 2.28)./0.05).^2);
specs = zeros(npts, nsub);
for ss = 1:nsub
    specs(:, ss) = polarities(ss)*cr + nag;
end
fids = ifft(ifftshift(specs, 1), [], 1);

avg = base_struct(ppm, sw, txfrq, Bo, npts);
if nsub > 1
    avg.fids = fids; avg.specs = specs;
    avg.dims = struct('t', 1, 'coils', 0, 'averages', 0, 'subSpecs', 2, 'extras', 0);
    avg.subspecs = nsub;
else
    avg.fids = fids; avg.specs = specs;
    avg.dims = struct('t', 1, 'coils', 0, 'averages', 0, 'subSpecs', 0, 'extras', 0);
    avg.subspecs = 1;
end
avg.sz = size(avg.fids);
avg.flags.averaged = 1;

% unaveraged (and optionally coil-resolved) container copy
unavg = base_struct(ppm, sw, txfrq, Bo, npts);
if with_coils
    big = zeros(npts, ncoils, navg, nsub);
    for cc = 1:ncoils
        for aa = 1:navg
            big(:, cc, aa, :) = reshape(fids, npts, 1, 1, nsub);
        end
    end
    unavg.dims = struct('t', 1, 'coils', 2, 'averages', 3, 'subSpecs', 4, 'extras', 0);
else
    big = zeros(npts, navg, nsub);
    for aa = 1:navg
        big(:, aa, :) = reshape(fids, npts, 1, nsub);
    end
    if nsub == 1
        big = reshape(big, npts, navg);
        unavg.dims = struct('t', 1, 'coils', 0, 'averages', 2, 'subSpecs', 0, 'extras', 0);
    else
        unavg.dims = struct('t', 1, 'coils', 0, 'averages', 2, 'subSpecs', 3, 'extras', 0);
    end
end
unavg.fids = big;
unavg.specs = fftshift(fft(big, [], 1), 1);
unavg.sz = size(big);
unavg.subspecs = nsub;
unavg.averages = navg;
unavg.flags.averaged = 0;
end

function s = base_struct(ppm, sw, txfrq, Bo, npts)
