    specs = mean(specs, sub.dims.coils);
end
if sub.dims.averages > 0
    specs = mean(specs, sub.dims.averages);
end
specs = reshape(specs, size(specs, 1), []);
pol = zeros(1, columns(specs));
for ss = 1:columns(specs)
    [~, idx] = max(abs(specs(:, ss)));
    pol(ss) = sign(specs(idx, ss));
end
end
