function s = describe(args)
if isempty(args); s = '(defaults)'; return; end
parts = {};
for ii = 1:numel(args)
    a = args{ii};
    if ischar(a); parts{end+1} = ['''' a ''''];
    elseif isstruct(a); parts{end+1} = ['struct(' strjoin(fieldnames(a)', ',') ')'];
    elseif isempty(a); parts{end+1} = '[]';
    else; parts{end+1} = num2str(double(a)); end
end
s = strjoin(parts, ', ');
end

function check_parses(name, fh)
try
    fh();
    fprintf('  %-20s ran without error\n', name);
catch err
    if ~isempty(strfind(lower(err.message), 'parse error'))
        fprintf('  %-20s PARSE ERROR: %s\n', name, err.message);
    else
        fprintf('  %-20s parsed OK (runtime error: %s)\n', name, strtrim(strsplit(err.message, sprintf('\n')){1}));
    end
end
end

function pol = cr_like_polarity(loaded)
specs = loaded.specs;
if loaded.dims.averages > 0
    specs = mean(specs, loaded.dims.averages);
end
specs = squeeze(specs);
pol = zeros(1, columns(specs));
for ss = 1:columns(specs)
    [~, idx] = max(abs(real(specs(:, ss))));
    pol(ss) = sign(real(specs(idx, ss)));
end
end
