% Realistic mini pipeline on a synthetic Philips-style MEGA acquisition whose
% peaks sit at true ppm positions of the loader's frequency axis:
%   load -> average -> take sub-spectra -> Hadamard-style sum/difference.
% Osprey builds diff1 = B - A and sum = A + B, i.e. it assumes that the
% common (non-edited) resonances have consistent polarity in A and B.
function dev_pipeline()
this_dir = fileparts(mfilename('fullpath'));
task_root = fileparts(this_dir);
source_root = fullfile(task_root, 'source');
addpath(fullfile(source_root, 'libraries', 'FID-A', 'inputOutput'));
addpath(fullfile(source_root, 'libraries', 'FID-A', 'processingTools'));
work = fullfile(task_root, 'outputs', 'devtests');
if ~exist(work, 'dir'); mkdir(work); end

npts = 1024; sw = 2000; txfrq = 127731000; navg = 4;
Bo = txfrq/42577000;
f = (-sw/2)+(sw/(2*npts)):sw/npts:(sw/2)-(sw/(2*npts));
ppm = (f/(Bo*42.577) + 4.68)';
cr  = exp(-0.5*((ppm - 3.02)./0.03).^2);      % common reference resonance
naa = exp(-0.5*((ppm - 2.01)./0.04).^2);      % common resonance
gaba = exp(-0.5*((ppm - 3.00)./0.05).^2);     % edited signal (ON only)

% Sub-spectrum A (edit-OFF) and B (edit-ON); B is acquired with the opposite
% receiver phase, i.e. 180 degrees, as Philips phase-cycles the ADC.
specA = cr + 0.8*naa;
specB = -(cr + 0.8*naa + 0.15*gaba);
path_sdat = write_sdat(work, 'pipeline', [specA specB], navg, sw, txfrq, npts);

for undo = [1 0]
    raw = io_loadspec_sdat(path_sdat, 2, 0, undo);
    raw = op_averaging(raw);
    subA = op_takesubspec(raw, 1);
    subB = op_takesubspec(raw, 2);
    diff1 = subB; diff1.specs = subB.specs - subA.specs; diff1.fids = subB.fids - subA.fids;
    summ  = subB; summ.specs  = subB.specs + subA.specs; summ.fids  = subB.fids + subA.fids;
    fprintf('undoPhaseCycle=%d: Cr(A)=%+.3f Cr(B)=%+.3f | Cr(diff1)=%+.3f Cr(sum)=%+.3f | GABA(diff1)=%+.3f\n', ...
        undo, peak(subA, 2.9, 3.15), peak(subB, 2.9, 3.15), ...
        peak(diff1, 2.9, 3.15), peak(summ, 2.9, 3.15), signed_at(diff1, 3.00));
end
end

function a = peak(in, lo, hi)
sub = op_freqrange(in, lo, hi);
spec = real(sub.specs);
[~, k] = max(abs(spec));
a = spec(k)/max(abs(spec(:)))*max(abs(spec(:)));  % signed peak amplitude
a = spec(k);
end

function a = signed_at(in, ppm_target)
[~, k] = min(abs(in.ppm - ppm_target));
a = real(in.specs(k));
end

function path_sdat = write_sdat(work, name, spectra, navg, sw, txfrq, npts)
path_sdat = fullfile(work, [name '.sdat']);
spar = fullfile(work, [name '.spar']);
nsub = columns(spectra);
nrows = nsub*navg;
src = ifft(ifftshift(spectra, 1), [], 1);
fid_data = zeros(npts, nrows);
for aa = 1:navg
    for ss = 1:nsub
        fid_data(:, (aa-1)*nsub + ss) = src(:, ss);
    end
end
packed = zeros(2, npts, nrows);
packed(1,:,:) = real(fid_data);
packed(2,:,:) = imag(fid_data);
fid = fopen(path_sdat, 'w', 'ieee-le');
fwriteVAXG(fid, packed(:), 'float32');
fclose(fid);
fid = fopen(spar, 'w');
fprintf(fid, 'samples : %d\nrows : %d\naverages : %d\n', npts, nrows, nrows);
fprintf(fid, 'synthesizer_frequency : %d\nsample_frequency : %d\n', txfrq, sw);
fprintf(fid, 'echo_time : 68\nrepetition_time : 2000\nscan_id : MEGA\nscan_date : 2026.07.13\n');
fprintf(fid, 'ap_size : 20\nlr_size : 20\ncc_size : 20\n');
fprintf(fid, 'ap_off_center : 0\nlr_off_center : 0\ncc_off_center : 0\n');
fprintf(fid, 'ap_angulation : 0\nlr_angulation : 0\ncc_angulation : 0\n');
fprintf(fid, 'patient_position : HFS\npatient_orientation : TRA\n');
fclose(fid);
end
