function MRSCont = base_cont(raw_unavg)
MRSCont = struct();
MRSCont.opts = struct();
MRSCont.flags.hasMM = 0;
MRSCont.raw = {raw_unavg};
end

function [avg, unavg] = make_struct(polarities, nsub, with_coils)
if nargin < 3; with_coils = false; end
npts = 512; navg = 3; ncoils = 2;

npts = 512; navg = 3; ncoils = 2;
sw = 2000; txfrq = 127731000;
Bo = txfrq/42577000;
f = (-sw/2)+(sw/(2*npts)):sw/npts:(sw/2)-(sw/(2*npts));
ppm = f/(Bo*42.577) + 4.68;
cr = exp(-0.5*((ppm(:) - 3.02)./0.03).^2);
nag = 0.4*exp(-0.5*((ppm(:) - 2.28)./0.05).^2);
specs = zeros(npts, nsub);
for ss = 1:nsub
    specs(:, ss) = polarities(ss)*cr + nag;
end
fids = ifft(ifftshift(specs, 1), [], 1);

avg = base_struct(ppm, sw, txfrq, Bo, npts);
if nsub > 1
    avg.fids = fids; avg.specs = specs;
    avg.dims = struct('t', 1, 'coils', 0, 'averages', 0, 'subSpecs', 2, 'extras', 0);
    avg.subspecs = nsub;
else
    avg.fids = fids; avg.specs = specs;
    avg.dims = struct('t', 1, 'coils', 0, 'averages', 0, 'subSpecs', 0, 'extras', 0);
    avg.subspecs = 1;
end
avg.sz = size(avg.fids);
avg.flags.averaged = 1;

% unaveraged (and optionally coil-resolved) container copy
unavg = base_struct(ppm, sw, txfrq, Bo, npts);
if with_coils
    big = zeros(npts, ncoils, navg, nsub);
    for cc = 1:ncoils
        for aa = 1:navg
            big(:, cc, aa, :) = reshape(fids, npts, 1, 1, nsub);
        end
    end
    unavg.dims = struct('t', 1, 'coils', 2, 'averages', 3, 'subSpecs', 4, 'extras', 0);
else
    big = zeros(npts, navg, nsub);
    for aa = 1:navg
        big(:, aa, :) = reshape(fids, npts, 1, nsub);
    end
    if nsub == 1
        big = reshape(big, npts, navg);
        unavg.dims = struct('t', 1, 'coils', 0, 'averages', 2, 'subSpecs', 0, 'extras', 0);
    else
        unavg.dims = struct('t', 1, 'coils', 0, 'averages', 2, 'subSpecs', 3, 'extras', 0);
    end
end
unavg.fids = big;
unavg.specs = fftshift(fft(big, [], 1), 1);
unavg.sz = size(big);
unavg.subspecs = nsub;
unavg.averages = navg;
unavg.flags.averaged = 0;
end

function s = base_struct(ppm, sw, txfrq, Bo, npts)
s = struct();
s.ppm = ppm;
s.t = (0:npts-1)/sw;
s.spectralwidth = sw;
s.dwelltime = 1/sw;
s.txfrq = txfrq;
s.Bo = Bo;
s.seq = 'MEGA';
s.te = 68; s.tr = 2000;
s.centerFreq = 4.68;
s.flags = struct('writtentostruct', 1, 'gotparams', 1, 'leftshifted', 0, 'filtered', 0, ...
    'zeropadded', 0, 'freqcorrected', 0, 'phasecorrected', 0, 'averaged', 0, ...
    'addedrcvrs', 1, 'subtracted', 0, 'writtentotext', 0, 'downsampled', 0, ...
    'isFourSteps', 0, 'isUnEdited', 0, 'isMEGA', 1, 'isHERMES', 0, 'isHERCULES', 0);
end

function show(tag, out, cont, pol)
pol_out = cr_polarity(out);
raw_cont = cont.raw{1};
pol_cont = cr_polarity(raw_cont);
fprintf('  %-20s factors=[%-8s] processed_pol=[%-10s] container_pol=[%-10s]\n', tag, ...
    num2str(pol), num2str(pol_out), num2str(pol_cont));
end

function pol = cr_polarity(in)
sub = op_freqrange(in, 2.8, 3.2);
specs = real(sub.specs);
if sub.dims.coils > 0
    specs = mean(specs, sub.dims.coils);
end
if sub.dims.averages > 0
    specs = mean(specs, sub.dims.averages);
end
specs = reshape(specs, size(specs, 1), []);
pol = zeros(1, columns(specs));
for ss = 1:columns(specs)
    [~, idx] = max(abs(specs(:, ss)));
    pol(ss) = sign(specs(idx, ss));
end
end

